<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'research.publications_eyebrow','Research outputs'))?></p><h1><?=View::escape(View::setting($siteContent??[],'research.publications_title','Research publications'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'research.publications_intro','Discover publications by FAST researchers and collaborators.'))?></p></div></section><section class="section"><div class="shell"><form class="public-search publication-search" method="get" action="<?=View::escape($baseUrl)?>research/publications"><label for="publication-directory-search">Find a publication</label><div><input id="publication-directory-search" name="q" type="search" maxlength="100" value="<?=View::escape($search)?>" placeholder="Title, DOI, journal"><select name="type" aria-label="Publication type"><option value="">All types</option><?php foreach($types as$type):?><option value="<?=View::escape($type['code'])?>"<?=$typeFilter===$type['code']?' selected':''?>><?=View::escape($type['name'])?></option><?php endforeach;?></select><select name="access" aria-label="Access type"><option value="">All access types</option><?php foreach(['open_access'=>'Open access','subscription'=>'Subscription','restricted'=>'Restricted','unknown'=>'Unknown']as$key=>$label):?><option value="<?=$key?>"<?=$accessFilter===$key?' selected':''?>><?=$label?></option><?php endforeach;?></select><input name="year" type="number" min="1800" max="<?=date('Y')+2?>" value="<?=View::escape($yearFilter)?>" placeholder="Year" aria-label="Publication year"><button class="button button-primary" type="submit">Search</button></div></form><?php if($result['items']===[]):?><div class="public-empty"><h2><?=$search===''&&$typeFilter===''&&$accessFilter===''&&$yearFilter===''?'Publication pages are being prepared':'No publications found'?></h2><p>Published research outputs will appear here.</p></div><?php else:?><div class="publication-list"><?php foreach($result['items']as$p):?><article class="publication-card"><p class="eyebrow"><?=View::escape($p['type_name'])?><?=isset($p['publication_year'])?' · '.(int)$p['publication_year']:''?></p><h2><a href="<?=View::escape($baseUrl)?>research/publications/<?=View::escape($p['slug'])?>"><?=View::escape($p['title'])?></a></h2><?php if($p['journal_name']):?><p class="publication-source"><?=View::escape($p['journal_name'])?></p><?php endif;?><?php if($p['abstract']):?><p><?=View::escape(mb_strimwidth($p['abstract'],0,260,'…'))?></p><?php endif;?><p class="card-meta"><?=View::escape(ucwords(str_replace('_',' ',$p['access_type'])))?><?php if($p['doi']):?> · DOI <?=View::escape($p['doi'])?><?php endif;?></p><a class="text-link" href="<?=View::escape($baseUrl)?>research/publications/<?=View::escape($p['slug'])?>">View publication →</a></article><?php endforeach;?></div><?php endif;?></div></section>
